args.code:
_ph = 'fwd'
_prev = None

def control(obs):
    global _ph, _prev
    h = float(obs.get('hitch_deg', 0.0) or 0.0)
    dt = float(obs.get('dt', 0.1) or 0.1)
    m = obs.get('motion', {}) or {}
    v = float(m.get('v_mps', 0.0) or 0.0)
    hold = float(m.get('hold_s', 0.0) or 0.0)
    if _ph == 'fwd':
        if abs(h) < 1.5:
            _ph = 'stop'
        else:
            return (0.0, 1.0, -23.0)
    if _ph == 'stop':
        if abs(v) < 0.05 and hold <= 0:
            _ph = 'rev'
            _prev = None
        else:
            return (0.0, 0.0, -23.0)
    rate = 0.0
    if _prev is not None and dt > 0:
        rate = (h - _prev) / dt
    _prev = h
    s = 1.5 * h + 0.3 * rate
    s = max(-34.0, min(34.0, s))
    return (s, -0.8, -23.0)

