    hold = float(m.get('hold_s', 0.0) or 0.0)
    rig = obs.get('rig', {}) or {}
    tr = rig.get('trailer_rear', [0.0, 0.0]) or [0.0, 0.0]
    y = float(tr[1]) if len(tr) > 1 else 0.0
    if _ph == 'fwd':
        if _t0 is None:
            _t0 = t
        if t - _t0 < 2.5:
            return (0.0, 0.5, -23.0)
        _ph = 'stop'
    if _ph == 'stop':
        if abs(v) < 0.05 and hold <= 0:
            _ph = 'rev'
            _prev = None
        else:
            return (0.0, 0.0, -23.0)
    rate = 0.0
    if _prev is not None and dt > 0:
        rate = (h - _prev) / dt
    _prev = h
    hd = max(-5.0, min(5.0, -6.0 * y))
    s = 3.0 * (h - hd) + 0.8 * rate
    s = max(-34.0, min(34.0, s))
    return (s, -0.5, -23.0)

